dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "input",
      "display": "false"
    }
  ],
  "context": {
    "group": "cfde",
    "contexts": {
      "Experimental biology": [
        "gene_info",
        "general_gene_info_function",
        "general_gene_info_go",
        "general_gene_info_pathway",
        "gtex_gene_info",
        "GTEx_gene",
        "GTEx_gene_kp",
        "fourDn_gene",
        "LINCS_gene",
        "IDG_gene",
        "exRNA_gene",
        "HuBMAP_gene",
        "SenNet_gene",
        "MetabolomicsWorkbench_gene",
        "MoTrPAC_gene",
        "GlyGen_gene",
        "KidsFirst_gene",
        "SPARC_gene",
        "HMP_gene",
        "A2CPS",
        "Bridge2AI",
        "A2CPS",
        "Bridge2AI"
      ],
      "Genetics": [
        "gene_info",
        "general_gene_info_function",
        "general_gene_info_go",
        "general_gene_info_pathway",
        "gtex_gene_info",
        "GTEx_gene",
        "GTEx_gene_kp",
        "fourDn_gene",
        "LINCS_gene",
        "IDG_gene",
        "exRNA_gene",
        "HuBMAP_gene",
        "SenNet_gene",
        "MetabolomicsWorkbench_gene",
        "MoTrPAC_gene",
        "GlyGen_gene",
        "KidsFirst_gene",
        "SPARC_gene",
        "HMP_gene",
        "A2CPS",
        "Bridge2AI",
        "A2CPS",
        "Bridge2AI"
      ],
      "Drug development": [
        "gene_info",
        "general_gene_info_function",
        "general_gene_info_go",
        "general_gene_info_pathway",
        "gtex_gene_info",
        "GTEx_gene",
        "GTEx_gene_kp",
        "fourDn_gene",
        "LINCS_gene",
        "IDG_gene",
        "exRNA_gene",
        "HuBMAP_gene",
        "SenNet_gene",
        "MetabolomicsWorkbench_gene",
        "MoTrPAC_gene",
        "GlyGen_gene",
        "KidsFirst_gene",
        "SPARC_gene",
        "HMP_gene",
        "A2CPS",
        "Bridge2AI",
        "A2CPS",
        "Bridge2AI"
      ]
    }
  },
  "tab groups": [
    {
      "label": "Gene information",
      "group id": "gene_info",
      "sections": [
        {
          "section": "general_gene_info_function",
          "label": "Gene function"
        },
        {
          "section": "general_gene_info_go",
          "label": "Gene ontology"
        },
        {
          "section": "general_gene_info_pathway",
          "label": "Gene pathways"
        }
      ]
    },
    {
      "label": "GTEx gene information",
      "group id": "gtex_gene_info",
      "sections": [
        {
          "section": "GTEx_gene",
          "label": "GTEx: Tissue specificity"
        },
        {
          "section": "GTEx_gene_kp",
          "label": "GTEx: Gene expression levels"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "general_gene_info_function",
      "header": "general_gene_info_function",
      "data point": {
        "type": "api",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "url": "https://rest.uniprot.org/uniprotkb/search?limit=1&query=(gene_exact:$gene)+AND+(organism_id:9606)+AND+(reviewed:true)&format:json&fields=cc_function",
        "data type": "json",
        "data wrapper": [
          "results",
          0,
          "comments",
          0,
          "texts",
          0
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Evidences",
            "raw field": "evidences"
          },
          {
            "type": "raw",
            "field name": "Function",
            "raw field": "value"
          }
        ],
        "rows as info cards": {
          "key": "Evidences"
        },
        "top rows": [
          "Function"
        ],
        "column formatting": {}
      }
    },
    {
      "section id": "general_gene_info_go",
      "header": "general_gene_info_go",
      "data point": {
        "type": "api",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "url": "https://mygene.info/v3/query?fields=go&q=$gene",
        "data type": "json",
        "data wrapper": [
          "hits"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "data to rows",
            "field name": "GO",
            "raw field": "go",
            "group by": [
              "evidence",
              "gocategory",
              "id",
              "pubmed",
              "qualifier",
              "term"
            ]
          },
          {
            "type": "raw",
            "field name": "evidence",
            "raw field": "evidence"
          },
          {
            "type": "raw",
            "field name": "gocategory",
            "raw field": "gocategory"
          },
          {
            "type": "raw",
            "field name": "id",
            "raw field": "id"
          },
          {
            "type": "raw",
            "field name": "pubmed",
            "raw field": "pubmed"
          },
          {
            "type": "raw",
            "field name": "qualifier",
            "raw field": "qualifier"
          },
          {
            "type": "raw",
            "field name": "term",
            "raw field": "term"
          }
        ],
        "top rows": [
          "evidence",
          "gocategory",
          "id",
          "pubmed",
          "qualifier",
          "term"
        ],
        "column formatting": {}
      }
    },
    {
      "section id": "general_gene_info_pathway",
      "header": "general_gene_info_pathway",
      "data point": {
        "type": "api",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "url": "https://mygene.info/v3/query?fields=pathway&q=$gene",
        "data type": "json",
        "data wrapper": [
          "hits"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "data to rows",
            "field name": "Pathway",
            "raw field": "pathway",
            "group by": [
              "id",
              "name"
            ]
          },
          {
            "type": "raw",
            "field name": "ID",
            "raw field": "id"
          },
          {
            "type": "raw",
            "field name": "Name",
            "raw field": "name"
          },
          {
            "type": "string to array",
            "separate by": ".",
            "take index": 0,
            "field name": "Key",
            "raw field": "_key0"
          }
        ],
        "top rows": [
          "ID",
          "Name",
          "Key"
        ],
        "column formatting": {}
      }
    },
    {
      "section id": "GTEx_gene",
      "header": "GTEx: Gene expression levels and tissue specificity",
      "data point": {
        "type": "api",
        "url": "https://cfde.hugeampkpnbi.org/api/bio/query/gtex-tstat?q=$gene",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Tstat",
            "raw field": "tstat"
          }
        ],
        "top rows": [
          "Tissue",
          "Biosample",
          "Tstat"
        ],
        "column formatting": {
          "Tstat": {
            "type": [
              "scientific notation",
              "render background percent"
            ]
          },
          "Tissue": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_dge_tissue?tissue=",
            "new tab": "true"
          }
        },
        "initial sort by": {
          "field": "Tissue"
        }
      },
      "filters": [
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        },
        {
          "field": "Biosample",
          "label": "Biosample",
          "type": "checkbox"
        }
      ],
      "visualizer": {
        "type": "bar plot",
        "label": "P-Value",
        "group by": "Tissue",
        "y axis field": "Tstat",
        "convert y -log10": null,
        "y ticks decimal point": "2",
        "render by": "Biosample",
        "y axis label": "Tstat",
        "x axis label": "Tissue / Biosample",
        "beta field": null,
        "hover content": [
          "Tissue",
          "Tstat"
        ],
        "thresholds": "calculate",
        "thresholds calculate": [
          [
            0.05,
            "/",
            "data length"
          ]
        ],
        "height": 300,
        "plot margin": {
          "top": 200,
          "bottom": 200,
          "left": 150,
          "right": 175
        }
      }
    },
    {
      "section id": "GTEx_gene_kp",
      "header": "GTEx: Gene expression levels and tissue specificity",
      "data point": {
        "type": "api",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/query/gene-expression?q=$gene",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Collection",
            "raw field": "collection"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Tissue Id",
            "raw field": "tissueId"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Biosample Id",
            "raw field": "biosampleId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Min TPM",
            "raw field": "minTpm"
          },
          {
            "type": "raw",
            "field name": "Max TPM",
            "raw field": "maxTpm"
          },
          {
            "type": "raw",
            "field name": "Median TPM",
            "raw field": "medianTpm"
          },
          {
            "type": "raw",
            "field name": "Q1 TPM",
            "raw field": "firstQuTpm"
          },
          {
            "type": "raw",
            "field name": "Q3 TPM",
            "raw field": "thirdQuTpm"
          },
          {
            "type": "raw",
            "field name": "Total Samples",
            "raw field": "nSamples"
          }
        ],
        "top rows": [
          "Tissue",
          "Tissue Id",
          "Biosample",
          "Biosample Id",
          "Dataset",
          "Min TPM",
          "Q1 TPM",
          "Median TPM",
          "Q3 TPM",
          "Max TPM",
          "Total Samples"
        ],
        "initial sort by": {
          "field": "Tissue"
        },
        "column formatting": {
          "Tissue": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_dge_tissue&tissue=",
            "new tab": "true"
          },
          "Dataset": {
            "type": [
              "link"
            ],
            "link to": "https://cmdga.org/search/?searchTerm=",
            "new tab": "true"
          },
          "Biosample Id": {
            "type": [
              "link"
            ],
            "link to": "https://www.ebi.ac.uk/ols4/search?ontology=uberon&q=",
            "new tab": "true"
          }
        }
      },
      "filters": [
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        },
        {
          "field": "Biosample",
          "label": "Biosample",
          "type": "checkbox"
        }
      ],
      "visualizer": {
        "type": "box plot",
        "label": "Absolute gene expression",
        "group by": "Tissue",
        "y axis field": {
          "min": "Min TPM",
          "max": "Max TPM",
          "median": "Median TPM",
          "q1": "Q1 TPM",
          "q3": "Q3 TPM"
        },
        "convert y -log10": null,
        "y ticks decimal point": "2",
        "render by": "Biosample",
        "y axis label": "TPM",
        "x axis label": "Tissue / Biosample",
        "hover content": [
          "Tissue",
          "Total Samples"
        ],
        "thresholds": "calculate",
        "thresholds calculate": [
          [
            0.05,
            "/",
            "data length"
          ]
        ],
        "height": 300,
        "plot margin": {
          "top": 200,
          "bottom": 200,
          "left": 150,
          "right": 175
        }
      },
      "pre filters": [
        {
          "field": "Collection",
          "value": "GTEx",
          "type": "search"
        }
      ]
    },
    {
      "section id": "fourDn_gene",
      "header": "4D Nucleome: Predicted gene-variant-disease links",
      "data point": {
        "type": "api",
        "url": "https://cfde.hugeampkpnbi.org/api/bio/query/4dn-gene?q=$tissue,$gene",
        "parameters": [
          "tissue",
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "search parameters": [
        {
          "parameter": "tissue",
          "label": "Set Tissue",
          "type": "list",
          "values": [
            {
              "label": "Blood",
              "value": "blood"
            },
            {
              "label": "Colon",
              "value": "colon"
            },
            {
              "label": "Embryonic tissue",
              "value": "embryonic_tissue"
            },
            {
              "label": "Olfactory nerve",
              "value": "olfactory_nerve"
            },
            {
              "label": "Skin of body",
              "value": "skin_of_body"
            },
            {
              "label": "Uterus",
              "value": "uterus"
            }
          ]
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Disease",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Credible set id",
            "raw field": "credibleSetId"
          },
          {
            "type": "join multi",
            "field name": "Clumped Region",
            "fields to join": [
              "chromosome",
              "clumpStart",
              "clumpEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "PPA",
            "raw field": "posteriorProbability"
          },
          {
            "type": "js math",
            "field name": "Log10(PPA)",
            "raw field": "PPA",
            "method": "log10"
          },
          {
            "type": "raw",
            "field name": "Lead SNP",
            "raw field": "leadSNP"
          },
          {
            "type": "raw",
            "field name": "View disease data",
            "raw field": "mondo_id"
          },
          {
            "type": "raw",
            "field name": "View on 4DN",
            "raw field": "tissue"
          }
        ],
        "top rows": [
          "Biosample",
          "PPA",
          "Lead SNP",
          "Clumped Region",
          "Disease",
          "View disease data",
          "View on 4DN"
        ],
        "features": [
          "Evidence"
        ],
        "Evidence": [
          "Tissue",
          "Biosample",
          "Source",
          "Dataset",
          "Credible set id"
        ],
        "column formatting": {
          "PPA": {
            "type": [
              "scientific notation"
            ]
          },
          "View on 4DN": {
            "type": [
              "link"
            ],
            "link to": "https://data.4dnucleome.org/search/?q=",
            "new tab": "true"
          },
          "View disease data": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_entity_disease?entity=disease&disease=",
            "new tab": "true"
          }
        }
      },
      "filters": [
        {
          "field": "PPA",
          "label": "PPA (>=)",
          "type": "search greater than"
        }
      ],
      "pre filters": [
        {
          "field": "PPA",
          "value": 0.01,
          "type": "search greater than"
        }
      ],
      "visualizer": {
        "label": "PPA",
        "type": "phewas plot",
        "group by": "Disease",
        "y axis field": "PPA",
        "convert y -log10": null,
        "y ticks decimal point": "2",
        "render by": "Biosample",
        "y axis label": "PPA",
        "x axis label": "Disease / Biosample",
        "beta field": null,
        "hover content": [
          "Tissue",
          "PPA",
          "Lead SNP"
        ],
        "thresholds": [
          0.01
        ],
        "label in black": "greater than",
        "height": 300,
        "plot margin": {
          "top": 50,
          "bottom": 200,
          "left": 150,
          "right": 175
        }
      }
    },
    {
      "section id": "LINCS_gene",
      "header": "Library of Integrated Network-based Cellular Signatures ",
      "data point": {
        "type": "api",
        "url": "https://cfde.hugeampkpnbi.org/api/bio/query/lincs-corr?q=$gene",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "ID",
            "raw field": "id"
          },
          {
            "type": "raw",
            "field name": "Name",
            "raw field": "name"
          },
          {
            "type": "raw",
            "field name": "Other ID",
            "raw field": "other_id"
          },
          {
            "type": "js math",
            "field name": "Correlation",
            "raw field": "correlation",
            "method": "abs"
          },
          {
            "type": "raw",
            "field name": "Correlated to",
            "raw field": "other_name"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "other_source"
          }
        ],
        "top rows": [
          "Correlated to",
          "Correlation",
          "Source"
        ]
      },
      "filters": [
        {
          "field": "Correlation",
          "label": "Correlation (>=)",
          "type": "search greater than"
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "checkbox"
        }
      ],
      "visualizer": {
        "label": "",
        "type": "phewas plot",
        "group by": "Name",
        "y axis field": "Correlation",
        "y ticks decimal point": "4",
        "render by": "Correlated to",
        "y axis label": "Correlation",
        "x axis label": "Correlated to",
        "beta field": null,
        "hover content": [
          "Correlation"
        ],
        "thresholds": [
          0.25
        ],
        "label in black": "greater than",
        "height": 300,
        "plot margin": {
          "top": 150,
          "bottom": 100,
          "left": 150,
          "right": 100
        }
      }
    },
    {
      "section id": "IDG_gene",
      "header": "IDG: Drug target level classifications",
      "data point": {
        "type": "graphQl",
        "url": "https://pharos-api.ncats.io/graphql",
        "index": "huge",
        "parameters": [
          "gene"
        ],
        "parameters type": "array",
        "data type": "json",
        "query string": "query targetDetails{\n\n target(q: { sym: \"$parameter\" }) {\n\n name\n\n tdl\n\n fam\n\n sym\n\n description\n\n novelty }}",
        "data wrapper": [
          "data",
          "target"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene Symbol",
            "raw field": "sym"
          },
          {
            "type": "raw",
            "field name": "Name",
            "raw field": "name"
          },
          {
            "type": "raw",
            "field name": "Family",
            "raw field": "fam"
          },
          {
            "type": "raw",
            "field name": "Visit Pharos",
            "raw field": "sym"
          },
          {
            "type": "join multi",
            "field name": "Gene(name)",
            "fields to join": [
              "Gene Symbol",
              "Name"
            ],
            "join by": [
              " (",
              ")"
            ]
          },
          {
            "type": "raw",
            "field name": "TDL",
            "raw field": "tdl"
          },
          {
            "type": "raw",
            "field name": "Description",
            "raw field": "description"
          },
          {
            "type": "raw",
            "field name": "Novelty",
            "raw field": "novelty"
          }
        ],
        "top rows": [
          "TDL",
          "Novelty",
          "Gene(name)",
          "Family",
          "Description",
          "Visit Pharos"
        ],
        "column formatting": {
          "TDL": {
            "type": [
              "value in class"
            ]
          },
          "Visit Pharos": {
            "type": [
              "link"
            ],
            "link to": "https://pharos.nih.gov/targets/",
            "new tab": "true",
            "link label": "Open"
          }
        }
      }
    },
    {
      "section id": "exRNA_gene",
      "header": "exRNA Research Portal ",
      "data point": {
        "type": "api",
        "url": "https://cfde.hugeampkpnbi.org/api/bio/query/exrna-gene-counts?q=$gene",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "filters": [
        {
          "field": "Cell line",
          "label": "Cell line",
          "type": "checkbox"
        },
        {
          "field": "Read count",
          "label": "Read count (>=)",
          "type": "search greater than"
        },
        {
          "field": "RNA binding protein",
          "label": "RNA binding protein",
          "type": "search",
          "features": [
            "autocomplete"
          ]
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "RNA binding protein",
            "raw field": "rbp"
          },
          {
            "type": "raw",
            "field name": "Genes produce RNAs",
            "raw field": "rbp"
          },
          {
            "type": "raw",
            "field name": "Cell line",
            "raw field": "cell_line"
          },
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene_symbol"
          },
          {
